import type {EnvNameV3} from '@smart/endpoint-directory';
import {AxiosError} from 'axios';
import {logger} from './logger';

export interface ErrorResponse {
  response: {
    data: {
      code: number;
      errors: {shortDescription: string; errorCodes?: string[]}[];
    };
  };
}

export type MulesoftApiSets<T = any> = {
  apiName: string;
  value: PromiseSettledResult<T>;
};

const createBffErrorObject = (error: any, apiName: string) => {
  if (error?.response?.data) {
    const {
      errors: muleSoftError,
      error: unknownError,
      code,
    } = error?.response?.data;
    if (muleSoftError) {
      const {shortDescription, errorCodes} = muleSoftError[0];
      const desc = `ERROR[${code}]: - ${apiName} / ${errorCodes[0]} - ${shortDescription}`;

      return {
        desc,
        statusCode: Number(code),
      };
    }
    if (unknownError) {
      return {
        desc: `ERROR[500]: - ${apiName} - ${unknownError}`,
        statusCode: 500,
      };
    }
  }

  return {
    desc: `ERROR[500]: - ${apiName} - ${error}`,
    statusCode: 500,
  };
};

export const userModelBffErrorHandling = (apiSets: MulesoftApiSets[]) => {
  const errors: {desc: string; statusCode: number}[] = [];

  for (const apiResponse of apiSets) {
    if (apiResponse.value.status === `rejected`) {
      errors.push(
        createBffErrorObject(apiResponse.value.reason, apiResponse.apiName),
      );
    }
  }

  return errors;
};

export const bffErrorHandling = (args: {
  error: any;
  apiName: string;
  cartId?: string;
  userUid: string;
  envName?: EnvNameV3;
}) => {
  const {error, apiName, cartId, userUid, envName} = args;

  if (error?.response?.data) {
    const {errors, error: badErrorStructure, code} = error.response.data;
    logger.error(
      {err: error.response.data, apiName, cartId, userUid},
      `******* API Error mulesoft endpoint name(s) ${apiName}`,
    );
    if (errors) {
      const [errorDetail] = errors;
      const errorShortDescription = errorDetail?.shortDescription!;

      const detailedErrorData = {
        data: error.response.data,
        // ...(error instanceof AxiosError && {config: error.config}),
      };

      const errorCodes =
        errorDetail?.errorCodes?.length && errorDetail?.errorCodes[0];
      const errorBody = errorCodes!
        ? `${errorShortDescription} - ${errorCodes}`
        : errorShortDescription;

      return {
        statusCode: code,
        body:
          envName !== `prod`
            ? JSON.stringify(detailedErrorData)
            : JSON.stringify(errorBody),
      };
    }

    if (badErrorStructure) {
      return {
        statusCode: 500,
        body: error.response.data?.error,
      };
    }
  }

  if (error.config) {
    delete error.config;
  }

  logger.error({err: error}, `**** Unknown API Error`);
  return {
    statusCode: 500,
    body: error,
  };
};

export const handleErrors = (errors: Record<string, Error>) => {
  let errMessages = ``;

  Object.entries(errors).forEach(([key, err]) => {
    if (err instanceof AxiosError) {
      const errMessage = handleAxiosError(err);
      errMessages += `${key} - ${errMessage}`;
    } else {
      errMessages += `${key} - ${err.message}`;
    }
  });

  return errMessages;
};

export const handleAxiosError = (err: any) => {
  if (err.response) {
    const {errors, error: unknownError, code} = err.response.data;
    const message =
      errors?.[0]?.shortDescription || unknownError || `Internal Server Error`;

    const errorBody = `${message} - ${code}`;

    return errorBody;
  }
  return err.message;
};

